def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

print("39455 factors:", prime_factorization(39455))
print("94175 factors:", prime_factorization(94175))
print("41000 factors:", prime_factorization(41000))
